<script id="rampart-strategy">
function createStrategy() {
  const ground = [3,6,7,11,8,2,4,9,5,12,1,0,15];
  const air = [10,13,14];
  const schedule = [
    [3,'"'cannon'],[13,'flak'],[6,'cannon'],[3,2],[13,2],[7,'cannon'],
    [3,3],[6,2],[13,3],[7,2],[6,3],[7,3],[10,'flak'],[10,2],
    [11,'cannon'],[11,2],[11,3],[10,3],[8,'cannon'],[8,2],[8,3]
  ];
  for(const slot of ground) if("'!schedule.some(a=>a[0]===slot)) schedule.push([slot,'"'cannon'],[slot,2],[slot,3]);
  schedule.push([14,'flak'],[14,2],[14,3]);
  return {
    plan(s) {
      if(s.wave<4) return [];
      const actions=[];
      let cash=s.gold;
      const tiers=s.slots.map(v=>v.turret?v.turret.tier:0);
      for(const [slot,kind] of schedule) {
        const build=typeof kind==='string';
        if(tiers[slot]>=(build?1:kind)) continue;
        const cost=(air.includes(slot)?80:90)*(build?1:kind-1);
        if(cash<cost) break;
        cash-=cost;
        actions.push(build?{op:'build',slot,type:kind}:{op:'upgrade',slot});
        tiers[slot]++;
      }
      return actions;
    },
    target(t,cs) {
      const radius=t.type==='cannon'?90:70;
      const damage=(t.type==='cannon'?[60,96,153]:[40,64,102])[t.tier-1];
      let best=-1, id=cs[0].id;
      for(const e of cs) {
        let score=0;
        for(const n of cs) {
          const dx=e.x-n.x,dy=e.y-n.y;
          if(dx*dx+dy*dy>radius*radius) continue;
          const d=Math.max(1,damage-n.armor);
          const urgency=1+1.6/(1+n.remaining/(10*n.speed));
          score+=urgency*(Math.min(n.hp,d)/damage+(n.hp<=d?0.4:0));
        }
        if(score>best){ best=score;id=e.id; }
      }
      return id;
    }
  };
}
</script>
<script id=\"rampart-sim\">
function rampartSimulate(createStrategy, seed, maxTicks) {
  const floor = Math.floor;
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a "'^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0; }; }
  const draw = mulberry32(seed);
  const stats = {
    grunt:[60,10,4,1,1,10], runner:[40,20,4,1,2,4], wisp:[50,12,6,2,3,3],
    brute:[150,6,9,3,4,3], splitter:[90,8,6,2,6,2], mender:[70,8,7,2,8,1],
    splitling:[0,12,1,1,999,0]
  };
  const guns = {
    bolt:[50,26,8,300,0,0,1,1], cannon:[90,60,24,260,90,0,1,0],
    frost:[70,10,12,240,0,30,1,1], lance:[120,180,36,360,0,0,1,0],
    flak:[80,40,10,320,70,0,0,1]
  };
  const ground=[[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const sky=[[0,6],[21,6],[21,11],[23,11]];
  const pads=[[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const slots=pads.map(([x,y],slot)=>({slot,x:100*x+50,y:100*y+50,turret:null}));
  const observer=rampartSimulate.record;
  const brain=createStrategy(), log=[], scale=[0,1000], types=Object.keys(guns);
  let living=[], queue=[], tick=0, wave=0, gold=250, baseHp=10, lastId=0, fallTick=-1;
  function generate(w) {
    const pool=Object.keys(stats).filter(k=>stats[k][4]<=w && stats[k][5]);
    const sum=pool.reduce((v,k)=>v+stats[k][5],0);
    return Array.from({length:4+floor(3*w/5)},()=>{
      let r=draw()%sum;
      for(const k of pool){r-=stats[k][5]; if(r<0) return k;}
    });
  }
  let preview=generate(1);
  function place(e) {
    const path=e.air?sky:ground;
    let p=e.progress;
    for(let i=1;i<path.length;i++){
      const [x,y]=path[i-1],dx=path[i][0]-x,dy=path[i][1]-y,len=(Math.abs(dx)+Math.abs(dy))*100;
      if(p<len || i===path.length-1) {
        e.x=100*x+50+Math.sign(dx)*p;
        e.y=100*y+50+Math.sign(dy)*p;
        e.dir=Math.sign(dx)===1?1:Math.sign(dy)===1?0:Math.sign(dy)===-1?2:3;
        break;
      }
      p-=len;
    }
    e.remaining=(e.air?2600:4600)-e.progress;
  }
  function spawn(type,w,progress=0,inheritedHp=0) {
    const a=stats[type], maxHp=inheritedHp||floor(a[0]*scale[w]/1000);
    const e={id:++lastId,type,wave:w,age:0,hp:maxHp,maxHp,progress,air:+(type==='"'wisp'),
      armor:type==='brute'?6+w:type==='grunt'?floor(w/4):0,speed:a[1],slowed:0};
    place(e);living.push(e);
  }
  function view(e) {
    const {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining}=e;
    return {id,type,hp,maxHp,x,y,air,armor,speed,slowed,remaining};
  }
  function sq(a,b){const dx=a.x-b.x,dy=a.y-b.y;return dx*dx+dy*dy;}
  function event(code,a,b) { log.push([tick,code,a,b]); }
  function fx(kind,x,y,extra) { if(observer) observer.event(tick,kind,x,y,extra); }
  function waveStart(){
    wave++;
    gold+=Math.min(50,floor(gold*5/100))+10+2*wave;
    if(wave>1) scale[wave]=floor(scale[wave-1]*108/100);
    const current=preview;
    preview=generate(wave+1);
    fx('wave',50,250,wave);
    const actions=brain.plan({tick,wave,gold,baseHp,enemies:living.map(view),nextWave:preview.slice(),
      slots:slots.map(s=>({...s,turret:s.turret?{type:s.turret.type,tier:s.turret.tier,spent:s.turret.spent}:null}))});
    if(Array.isArray(actions)) for(const act of actions.slice(0,32)) {
      if("'!act || !Number.isInteger(act.slot) || !slots[act.slot]) continue;
      const s=slots[act.slot], t=s.turret, k=act.type;
      if(act.op==='"'build' && "'!t && types.includes(k) && gold>=guns[k][0]){
        const spent=guns[k][0];gold-=spent;
        s.turret={type:k,tier:1,spent,cd:0,aim:Math.PI,damage:guns[k][1]};
        event('"'B',s.slot,types.indexOf(k));fx('build',s.x,s.y,k);
      } else if(act.op==='upgrade' && t && t.tier<3 && gold>=guns[t.type][0]*t.tier){
        const cost=guns[t.type][0]*t.tier;
        gold-=cost;t.spent+=cost;t.tier++;t.damage=floor(t.damage*16/10);
        event('U',s.slot,t.tier);fx('upgrade',s.x,s.y,t.tier);
      } else if(act.op==='sell' && t){
        gold+=floor(t.spent*70/100);s.turret=null;event('S',s.slot,0);fx('sell',s.x,s.y,t.type);
      }
    }
    current.forEach((type,i)=>queue.push({tick:tick+4*i,wave,i,type}));
    queue.sort((a,b)=>a.tick-b.tick || a.wave-b.wave || a.i-b.i);
  }
  function snapshot(){
    if(observer) observer.frame(tick,wave,gold,baseHp,preview,slots,living);
  }
  for(;tick<maxTicks;tick++){
    if(tick>=20 && (tick-20)%40===0) waveStart();
    while(queue.length && queue[0].tick===tick){
      const q=queue.shift();spawn(q.type,q.wave);
    }
    for(let i=0;i<living.length;i++){
      const e=living[i];
      e.progress+=e.slowed?floor(e.speed*60/100):e.speed;
      place(e);
      if(e.remaining<=0){
        baseHp-=stats[e.type][3];event('L',e.id,baseHp);fx('leak',2350,1150,e.type);
        living.splice(i--,1);
        if(baseHp<=0){fallTick=tick;event('F',wave,0);fx('fall',2350,1150,wave);break;}
      }
    }
    if(fallTick>=0){snapshot();break;}
    for(const e of living){
      e.age++;
      if(e.type==='mender' && e.age%20===0){
        fx('heal',e.x,e.y,e.id);
        for(const n of living) if(sq(e,n)<=22500) n.hp=Math.min(n.maxHp,n.hp+floor(n.maxHp*8/100));
      }
    }
    for(const s of slots){
      const t=s.turret;
      if("'!t) continue;
      if(t.cd>0 && --t.cd>0) continue;
      const g=guns[t.type],range=g[3]+30*(t.tier-1);
      const candidates=living.filter(e=>g[6+e.air] && sq(s,e)<=range*range);
      if(!candidates.length) continue;
      let target;
      if(brain.target){
        const id=brain.target({slot:s.slot,type:t.type,tier:t.tier,x:s.x,y:s.y,range},candidates.map(view));
        target=candidates.find(e=>e.id===id);
      }
      if(!target) target=candidates.reduce((a,b)=>b.remaining<a.remaining?b:a);
      if(observer) {
        t.aim=Math.atan2(target.x-s.x,target.y-s.y);
        fx('"'shot',s.x,s.y,{type:t.type,x:target.x,y:target.y,air:target.air,slot:s.slot});
      }
      t.cd=g[2];
      for(const e of (g[4]?living:[target])){
        if("'!g[6+e.air] || (g[4] && sq(target,e)>g[4]*g[4])) continue;
        e.hp-=Math.max(1,t.damage-(t.type==='"'lance'?0:e.armor));
        if(g[5]) e.slowed=g[5];
      }
      const dead=living.filter(e=>e.hp<=0);
      if(dead.length) living=living.filter(e=>e.hp>0);
      for(const e of dead){
        gold+=stats[e.type][2];event('K',e.id,s.slot);fx('kill',e.x,e.y,e.type);
        if(e.type==='splitter') for(let j=0;j<3;j++) spawn('splitling',e.wave,e.progress,Math.max(1,floor(e.maxHp/4)));
      }
    }
    for(const e of living) if(e.slowed>0) e.slowed--;
    snapshot();
  }
  let hash=0x811c9dc5;
  const serial=JSON.stringify(log);
  for(let i=0;i<serial.length;i++) hash=Math.imul(hash"'^serial.charCodeAt(i),0x01000193);
  return {score:Math.round((tick-20)*100/40)/100,fallTick,log,hash:(hash>>>0).toString(16).padStart(8,'"'0')};
}
</script>
