      }
      t.cd=g[2];
      for(const e of (g[4]?living:[target])){
        if("'!g[6+e.air] || (g[4] && sq(target,e)>g[4]*g[4])) continue;
        e.hp-=Math.max(1,t.damage-(t.type==='"'lance'?0:e.armor));
        if(g[5]) e.slowed=g[5];
      }
      const dead=living.filter(e=>e.hp<=0);
      if(dead.length) living=living.filter(e=>e.hp>0);
      for(const e of dead){
        gold+=stats[e.type][2];event('K',e.id,s.slot);fx('kill',e.x,e.y,e.type);
        if(e.type==='splitter') for(let j=0;j<3;j++) spawn('splitling',e.wave,e.progress,Math.max(1,floor(e.maxHp/4)));
      }
    }
    for(const e of living) if(e.slowed>0) e.slowed--;
